function Canon([object]$Value){function Normalize([object]$Item){if($null-eq$Item){return $null};if($Item-is[string]-or$Item-is[bool]-or$Item-is[int]-or$Item-is[long]){return $Item};if($Item-is[Collections.IDictionary]){$ordered=[ordered]@{};foreach($key in @($Item.Keys|Sort-Object)){$ordered[[string]$key]=Normalize $Item[$key]};return $ordered};if($Item-is[Collections.IEnumerable]){return,@($Item|ForEach-Object{Normalize $_})};$ordered=[ordered]@{};foreach($property in @($Item.PSObject.Properties|Sort-Object Name)){$ordered[$property.Name]=Normalize $property.Value};$ordered};(Normalize $Value)|ConvertTo-Json -Compress -Depth 32}
function SafeExisting([string]$Path,[switch]$Directory){if([string]::IsNullOrWhiteSpace($Path)-or-not[IO.Path]::IsPathRooted($Path)){throw 'FINALIZE_POLICY_PATH_INVALID'};$full=[IO.Path]::GetFullPath($Path);$item=Get-Item -LiteralPath $full -Force;if(-not$Directory-and$item.PSIsContainer){throw 'FINALIZE_POLICY_FILE_REQUIRED'};$cursor=$item;while($null-ne$cursor){if($cursor.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'FINALIZE_POLICY_REPARSE_FORBIDDEN'};$cursor=if($cursor-is[IO.DirectoryInfo]){$cursor.Parent}else{$cursor.Directory}};$full}
function SafeNew([string]$Path){if([string]::IsNullOrWhiteSpace($Path)-or-not[IO.Path]::IsPathRooted($Path)){throw 'FINALIZE_POLICY_PATH_INVALID'};$full=[IO.Path]::GetFullPath($Path);if(Test-Path -LiteralPath $full){throw 'FINALIZE_POLICY_OUTPUT_COLLISION'};$parent=SafeExisting (Split-Path -Parent $full) -Directory;$full}
function SystemSshKeygen(){ $system=[Environment]::SystemDirectory;if([string]::IsNullOrWhiteSpace($system)-or-not[IO.Path]::IsPathRooted($system)){throw 'FINALIZE_POLICY_SYSTEM_DIRECTORY_INVALID'};SafeExisting (Join-Path $system 'OpenSSH\ssh-keygen.exe') }
function PublicParts([string]$Path){$raw=[IO.File]::ReadAllBytes((SafeExisting $Path));try{$parts=([Text.Encoding]::ASCII.GetString($raw)).Trim()-split'\s+';$blob=[Convert]::FromBase64String($parts[1])}catch{throw 'FINALIZE_POLICY_PUBLIC_KEY_INVALID'};if($parts.Count-lt2-or$parts[0]-cne'ssh-ed25519'-or$blob.Length-ne51-or[Text.Encoding]::ASCII.GetString($blob,4,11)-cne'ssh-ed25519'){throw 'FINALIZE_POLICY_PUBLIC_KEY_INVALID'};[ordered]@{normalized=$parts[0]+' '+$parts[1];raw=$raw}}
