function VerifySignature([object]$Loaded,[string]$PublicKey,[string]$Signature){$public=PublicParts $PublicKey;$signaturePath=SafeExisting $Signature;$ssh=SystemSshKeygen;$temporary=Join-Path ([IO.Path]::GetTempPath()) ('finalize-policy-verify-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temporary)|Out-Null;try{$allowed=Join-Path $temporary 'allowed_signers';$copy=Join-Path $temporary 'policy.sig';[IO.File]::WriteAllText($allowed,($Identity+' '+$public.normalized+[char]10),[Text.Encoding]::ASCII);[IO.File]::WriteAllBytes($copy,[IO.File]::ReadAllBytes($signaturePath));$psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$ssh;$psi.Arguments='-Y verify -f "'+$allowed+'" -I '+$Identity+' -n '+$Namespace+' -s "'+$copy+'"';$psi.UseShellExecute=$false;$psi.RedirectStandardInput=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$process=[Diagnostics.Process]::Start($psi);$process.StandardInput.Write([Text.Encoding]::UTF8.GetString($Loaded.raw));$process.StandardInput.Close();if(-not$process.WaitForExit(10000)){$process.Kill();throw 'FINALIZE_POLICY_SIGNATURE_TIMEOUT'};if($process.ExitCode-ne0){throw 'FINALIZE_POLICY_SIGNATURE_INVALID'}}finally{Remove-Item -LiteralPath $temporary -Recurse -Force -ErrorAction SilentlyContinue};if((HashFile $Loaded.path)-cne(HashBytes $Loaded.raw)){throw 'FINALIZE_POLICY_POST_VERIFY_DRIFT'}}
function AssertInstalledAcl([string]$Path,[string]$RuntimeSid){$acl=Get-Acl -LiteralPath $Path;if(-not$acl.AreAccessRulesProtected){throw 'FINALIZE_POLICY_ACL_INVALID'};$allowed=@('S-1-5-18','S-1-5-32-544');$owner=([Security.Principal.NTAccount]::new([string]$acl.Owner)).Translate([Security.Principal.SecurityIdentifier]).Value;if($owner-notin$allowed-or$RuntimeSid-in$allowed){throw 'FINALIZE_POLICY_ACL_INVALID'};$write=[Security.AccessControl.FileSystemRights]::WriteData-bor[Security.AccessControl.FileSystemRights]::CreateFiles-bor[Security.AccessControl.FileSystemRights]::AppendData-bor[Security.AccessControl.FileSystemRights]::WriteAttributes-bor[Security.AccessControl.FileSystemRights]::WriteExtendedAttributes-bor[Security.AccessControl.FileSystemRights]::Delete-bor[Security.AccessControl.FileSystemRights]::ChangePermissions-bor[Security.AccessControl.FileSystemRights]::TakeOwnership;$runtimeRead=$false;foreach($ace in $acl.Access){$sid=$ace.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value;if($ace.AccessControlType-eq'Allow'-and(([int64]$ace.FileSystemRights-band[int64]$write)-ne0)-and$sid-notin$allowed){throw 'FINALIZE_POLICY_ACL_INVALID'};if($sid-ceq$RuntimeSid-and$ace.AccessControlType-eq'Allow'-and(($ace.FileSystemRights-band[Security.AccessControl.FileSystemRights]::ReadAndExecute)-ne0)-and(([int64]$ace.FileSystemRights-band[int64]$write)-eq0)){$runtimeRead=$true}};if(-not$runtimeRead){throw 'FINALIZE_POLICY_ACL_INVALID'}}
function SetInstalledAcl([string]$Path,[string]$RuntimeSid){$item=Get-Item -LiteralPath $Path -Force;$acl=Get-Acl -LiteralPath $Path;$acl.SetAccessRuleProtection($true,$false);foreach($rule in @($acl.Access)){$acl.RemoveAccessRuleSpecific($rule)};$system=[Security.Principal.SecurityIdentifier]::new('S-1-5-18');$admins=[Security.Principal.SecurityIdentifier]::new('S-1-5-32-544');$runtime=[Security.Principal.SecurityIdentifier]::new($RuntimeSid);$acl.SetOwner($admins);$inherit=if($item.PSIsContainer){[Security.AccessControl.InheritanceFlags]'ContainerInherit,ObjectInherit'}else{[Security.AccessControl.InheritanceFlags]::None};foreach($principal in @($system,$admins)){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($principal,[Security.AccessControl.FileSystemRights]::FullControl,$inherit,[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow))|Out-Null};$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($runtime,[Security.AccessControl.FileSystemRights]::ReadAndExecute,$inherit,[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow))|Out-Null;Set-Acl -LiteralPath $Path -AclObject $acl;AssertInstalledAcl $Path $RuntimeSid}
function AssertMachineRuntime([string]$Common,[string]$RuntimeSid,[string]$ExpectedHash){$app=SafeExisting (Join-Path $Common 'AI_SCALPER') -Directory;$runtime=SafeExisting (Join-Path $app 'phase-d-python-runtime') -Directory;$python=SafeExisting (Join-Path $runtime 'python.exe');foreach($path in @($app,$runtime,$python)){AssertInstalledAcl $path $RuntimeSid};foreach($item in Get-ChildItem -LiteralPath $runtime -Recurse -Force){if($item.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'FINALIZE_POLICY_RUNTIME_REPARSE_FORBIDDEN'};AssertInstalledAcl $item.FullName $RuntimeSid};if((HashFile $python)-cne$ExpectedHash){throw 'FINALIZE_POLICY_RUNTIME_HASH_MISMATCH'};[ordered]@{path=$python;root=$runtime}}
function Result([string]$Mode,[string]$Status,[object]$Extra){$value=[ordered]@{authorization_granted=$false;mode=$Mode;order_capability='DISABLED';private_key_exported=$false;schema_version='finex-phase-d-trusted-finalize-python-policy-result-v1';status=$Status};foreach($property in $Extra.GetEnumerator()){$value[$property.Key]=$property.Value};Write-Output ((Canon $value)+[char]10)}

if($SetupKey){$private=SafeNew $AuthorityPrivateKeyPath;$public=$private+'.pub';if(Test-Path -LiteralPath $public){throw 'FINALIZE_POLICY_OUTPUT_COLLISION'};$ssh=SystemSshKeygen;$psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$ssh;$psi.Arguments='-q -t ed25519 -N "" -C "'+$Identity+'" -f "'+$private+'"';$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$process=[Diagnostics.Process]::Start($psi);if(-not$process.WaitForExit(10000)){$process.Kill();throw 'FINALIZE_POLICY_KEY_SETUP_TIMEOUT'};if($process.ExitCode-ne0-or-not(Test-Path -LiteralPath $private -PathType Leaf)-or-not(Test-Path -LiteralPath $public -PathType Leaf)){Remove-Item -LiteralPath $private -Force -ErrorAction SilentlyContinue;Remove-Item -LiteralPath $public -Force -ErrorAction SilentlyContinue;throw 'FINALIZE_POLICY_KEY_SETUP_FAILED'};PublicParts $public|Out-Null;Result 'SetupKey' 'KEY_CREATED' ([ordered]@{authority_public_key_path=$public});return}
if($Prepare){PublicParts $AuthorityPublicKeyPath|Out-Null;$sourcePython=SafeExisting $PythonPath;$common=[Environment]::GetFolderPath([Environment+SpecialFolder]::CommonApplicationData);if([string]::IsNullOrWhiteSpace($common)-or-not[IO.Path]::IsPathRooted($common)){throw 'FINALIZE_POLICY_INSTALL_ROOT_INVALID'};$fixedPython=[IO.Path]::GetFullPath((Join-Path $common 'AI_SCALPER\phase-d-python-runtime\python.exe'));$output=SafeNew $PolicyPath;$value=[ordered]@{python_path=$fixedPython;python_sha256=HashFile $sourcePython;schema_version=$Schema};$raw=[Text.UTF8Encoding]::new($false).GetBytes((Canon $value)+[char]10);$stream=[IO.File]::Open($output,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$stream.Write($raw,0,$raw.Length);$stream.Flush($true)}finally{$stream.Dispose()};LoadPolicy $output|Out-Null;Result 'Prepare' 'POLICY_PREPARED_UNSIGNED' ([ordered]@{policy_path=$output;policy_sha256=HashBytes $raw});return}
